def countVertex(N: int, edges: list[tuple[int, int]]) -> int:
    if N == 1:
        return 1

    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (N + 1)
    res = 0

    def dfs(node):
        nonlocal res
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                res += 1
                dfs(neighbor)

    dfs(1)
    return res
